const incoming = $input.first().json;
if (incoming.headers?.['x-nexus-secret'] !== $env.N8N_SECRET) throw new Error('Invalid webhook secret');
const body = incoming.body || incoming;
for (const key of ['ticket_id', 'query']) if (!body[key]) throw new Error(`Missing ${key}`);
const prompt = `You are a customer support AI. Analyse the customer message below. Return only JSON: {sentiment: positive|neutral|negative, urgency: low|medium|high, intent: short label, confidence: number 0 to 1, ai_response: helpful concise reply}. Do not invent policy or compensation. Customer message: ${body.query}`;
return [{ json: { ticket_id: body.ticket_id, geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json' } } } }];

const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no support analysis');
const result = JSON.parse(raw);
const source = $('Prepare support retry').first().json;
return [{ json: { ticket_id: source.ticket_id, sentiment: ['positive','neutral','negative'].includes(result.sentiment) ? result.sentiment : 'neutral', urgency: ['low','medium','high'].includes(result.urgency) ? result.urgency : 'low', intent: String(result.intent || 'general inquiry').slice(0, 120), confidence: Math.max(0, Math.min(1, Number(result.confidence) || 0.5)), ai_response: String(result.ai_response || '').slice(0, 2000) } }];
